      chatIds.forEach(id => {
        const app = Object.values($storex.ui.openApps).find(app => app.tabId === id)
        if (app) {
          $storex.ui.closeApp(app)
        }
      })

      // Remove from store
      chatIds.forEach(id => {
        delete state.chats[id]
      })

